def style(role):
    return {k: v for k, v in hp.comparison_style(role).items() if k in ('color', 'linestyle')}


def head(section, title, message):
    fig = plt.figure(figsize=(13.33, 8))
    fig.text(.06, .965, 'HYBRID MODEL / '+section.upper(), color=hp.DEFAULT_COLOR, fontsize=11, va='top')
    fig.text(.06, .91, title, fontsize=27, va='top')
    fig.text(.06, .835, message, fontsize=17, va='top')
    fig.add_artist(Line2D([.06, .96], [.785, .785], transform=fig.transFigure,
                          color=hp.DEFAULT_COLOR, lw=1.2))
    return fig


def note(fig, text, y=.105, size=14):
    fig.text(.075, y, text, fontsize=size, color=GREY, va='top', linespacing=1.4)


def logq(ax):
    ax.set(xscale='log', xlim=Q_RANGE, xlabel=hp.LRES_LABEL)
    ax.xaxis.set_major_locator(FixedLocator([.05, .2, 1, 5, 20]))
    ax.xaxis.set_major_formatter(FuncFormatter(lambda x, pos: f'{x:g}'))
    ax.xaxis.set_minor_formatter(NullFormatter())
    hp.frame_axes(ax, minor=False)


def legend(fig, entries, y=.725, size=15):
    fig.legend(handles=[Line2D([], [], lw=2.6, label=label, **style(role)) for label, role in entries],
               loc='lower center', bbox_to_anchor=(.51, y), ncol=len(entries), fontsize=size,
               handlelength=3.2, columnspacing=1.3)


