def our_wake():
    report = INPUT.json('wake_profile_report')
    data = INPUT.npz('wake_profile')
    None
    states = report['profile_states']
    names = report['profile_moment_names']
    moments = data['profile_moments']
    fig = head('Our test, not an implementation of Efficient Wake', 'Ad hoc: reshape the existing wake particles, then restore conservation',
               'The paper motivates the direction of the change, not our particle-by-particle prescription.')
    fig.text(.08, .735, 'Shift momenta and angles; change particle numbers; conserve the net wake four-momentum.', fontsize=16)
    for left, token, ylabel in [(.105, 'energy_pt', r'Energy-weighted mean $p_T$ [GeV]'),
                                 (.59, 'energy_radius', 'Mean distance to parton axis')]:
        ax = fig.add_axes([left, .35, .34, .27])
        for offset, state, role, label in [(-.23, 'original', 'default', 'Original'),
                                         (0, 'proposal_1', 'blue', 'Requested shape'),
                                         (.23, 'separate_1', 'vermillion', 'Conserved test')]:
            m = moments[states.index(state)]
            denominator = 'energy_with_defined_axis' if token == 'energy_radius' else 'energy'
            values = m[:, names.index(token)]/m[:, names.index(denominator)]
            ax.bar(np.arange(2)+offset, values, width=.22, color=style(role)['color'], label=label)
            for j, value in enumerate(values):
                ax.text(j+offset, value+.07, f'{value:.2f}', ha='center', fontsize=12)
        ax.set(xticks=[0, 1], xticklabels=['Positive wake', 'Subtracted wake'], ylabel=ylabel,
               ylim=(0, 2.9) if token == 'energy_pt' else (0, 4.2))
        ax.tick_params(labelsize=13)
        ax.yaxis.label.set_fontsize(15)
        hp.frame_axes(ax)
    legend(fig, [('Original', 'default'), ('Requested shape', 'blue'), ('Conserved test', 'vermillion')], y=.65, size=14)
    fig.text(.08, .235, 'Similar: positive wake is harder; more energy stays near the jet.', fontsize=19, color=hp.DEFAULT_COLOR)
    fig.text(.08, .175, 'Different: narrowing is weaker than requested; the negative particles soften.', fontsize=19)
    note(fig, 'Local example, not a bank average. Signed energy and momentum are conserved; no hard recoil is added.\nAxes use nearest hard partons, not true deposition histories. This is a sensitivity test, not a theory-error model.', y=.10, size=12)
    save(fig, 'our_wake', 'How our deformation differs from the paper', ('Q6',))


def fixed_wake():
    data = INPUT.npz('wake_fixed')
    point = INPUT.json('wake_fixed_point')
    fig = head('Wake effect before refitting', 'Grooming does not remove changes in jet yield or sample selection',
               rf'Same events and parameters: $\pi T L_{{\rm res}}={point["physical_pi_T_Lres"]:.2f}$, $\kappa_{{\rm sc}}={point["kappa_sc"]:.3f}$.')
    for j, name in enumerate(dict.fromkeys(data['features'][:, 0])):
        ix = np.flatnonzero(data['features'][:, 0] == name)
        x = data['features'][ix, 1:].astype(float).mean(1)
        ax = fig.add_axes([.075+j*.305, .32, .255, .35])
        change = 100*(data['response'][ix]-1)
        error = 100*np.sqrt(np.diag(data['response_covariance'])[ix])
        ax.axhline(0, color=GREY, lw=1)
        ax.plot(x, change, lw=2.5, **style('vermillion'))
        ax.fill_between(x, change-error, change+error, color=style('vermillion')['color'], alpha=.2)
        ax.set(xscale='log', xlim=(.001, .4), ylim=(-10, 50), xlabel=r'$r_g$',
               title=['158-200 GeV jets', '200-315 GeV jets', '315-501 GeV jets'][j])
        if j == 0:
            ax.set_ylabel('Change in differential yield [%]')
            ax.yaxis.label.set_fontsize(15)
        ax.xaxis.set_major_locator(FixedLocator([.001, .01, .1, .4]))
        ax.xaxis.set_major_formatter(FuncFormatter(lambda x, pos: f'{x:g}'))
        ax.xaxis.set_minor_formatter(NullFormatter())
        ax.title.set_fontsize(17)
        ax.tick_params(labelsize=13)
        hp.frame_axes(ax, minor=False)
        v = 100*(data['yield_ratios'][j]-1)
        s = 100*np.sqrt(data['yield_ratio_covariance'][j, j])
        fig.text(.202+j*.305, .22, rf'Total tagged yield: $+{v:.1f}\pm{s:.1f}\%$', ha='center', fontsize=18)
    note(fig, 'Reshaped relative to original wake. Bands: paired simulation errors. No parameter compensation in this plot.', y=.125, size=13)
    save(fig, 'fixed_wake', 'What changes in the groomed-radius observable at fixed parameters', ('Q6',))


